// Importing necessary modules and components
import React from 'react';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import '../CSS/hero.css';
import useFetch from './useFetch'; // Importing the useFetch hook

// Defining the HeroSection component
function HeroSection() {
  // Using the useFetch hook to fetch the movie data from the TMDB API
  const { data: movies, loading } = useFetch(
    'https://api.themoviedb.org/3/movie/popular?api_key=499d99db6ce23991d21afde0deede0f1'
  );

  // Defining settings for the Slider component
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
  };

  // Rendering the hero section with a carousel of movie posters
  return (
    <section className="hero-section">
      {loading ? (
        <div>Loading...</div>
      ) : (
        <Slider {...settings}>
          {movies.map((movie) =>
            movie.poster_path ? (
              <div key={movie.id}>
                <img
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
                  alt={movie.title}
                />
              </div>
            ) : null
          )}
        </Slider>
      )}
    </section>
  );
}

// Exporting the HeroSection component as the default export
export default HeroSection;



